public static int largestRectangleArea(int[] heights) {
    int n = heights.length;
    int[] left = new int[n];
    int[] right = new int[n];
    int maxArea = 0;

    for (int i = 1; i < n; i++) {
        int currHeight = heights[i];
        int leftIdx = i - 1;
        while (leftIdx >= 0 && heights[leftIdx] >= currHeight) {
            leftIdx = left[leftIdx];
        }
        left[i] = leftIdx;
    }

    for (int i = n - 2; i >= 0; i--) {
        int currHeight = heights[i];
        int rightIdx = i + 1;
        while (rightIdx < n && heights[rightIdx] >= currHeight) {
            rightIdx = right[rightIdx];
        }
        right[i] = rightIdx;
    }

    for (int i = 0; i < n; i++) {
        maxArea = Math.max(maxArea, heights[i] * (right[i] - left[i] - 1));
    }

    return maxArea;
}
