public static int[] diagonalOrder(int[][] mat) {
    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int i = 0;
    for (int r = 0; r < m + n - 1; r++) {
        int c = r < n ? r : m - 1;
        int d = r < n ? 1 : -1;
        while (c >= 0 && c < m && r - c >= 0 && r - c < n) {
            result[i++] = mat[c][r - c];
            c += d;
        }
    }
    return result;
}
