public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    for (int i = 1; i <= 9; i++) {
        String num = String.valueOf(i);
        if (num.length() == n && isCenterSymmetric(num)) {
            result.add(num);
        }
    }
    return result;
}

private static boolean isCenterSymmetric(String num) {
    int len = num.length();
    for (int i = 0; i < len / 2; i++) {
        if (num.charAt(i) != num.charAt(len - i - 1)) {
            return false;
        }
    }
    return true;
}
