public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    for (int i = 1; i <= 9; i++) {
        result.add(i);
    }
    for (int i = 10; i <= n; i++) {
        int digit = i % 10;
        int index = result.indexOf(digit);
        result.add(index, i);
    }
    return result;
}
